<form class="vv-auth-form" data-vendor-reset novalidate><div class="vv-form-message" data-form-message role="status" hidden></div><div class="vc-field"><label for="vendor-reset-password">New password</label><div class="vv-input-wrap"><i class="fa-solid fa-lock"></i><input class="vc-input" id="vendor-reset-password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="Create a strong password"><button type="button" data-password-toggle="vendor-reset-password" aria-label="Show password"><i class="fa-regular fa-eye"></i></button></div><small class="vv-error" data-error-for="password"></small></div><div class="vv-password-rules"><span data-rule="length"><i class="fa-solid fa-circle"></i> 12+ characters</span><span data-rule="upper"><i class="fa-solid fa-circle"></i> Uppercase</span><span data-rule="lower"><i class="fa-solid fa-circle"></i> Lowercase</span><span data-rule="number"><i class="fa-solid fa-circle"></i> Number</span><span data-rule="special"><i class="fa-solid fa-circle"></i> Special</span></div><div class="vc-field"><label for="vendor-reset-confirm">Confirm new password</label><div class="vv-input-wrap"><i class="fa-solid fa-lock"></i><input class="vc-input" id="vendor-reset-confirm" name="confirm_password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="Repeat the new password"></div><small class="vv-error" data-error-for="confirm_password"></small></div><button class="vc-btn primary vv-submit" type="submit"><span>Update demo password</span><i class="fa-solid fa-check"></i></button></form><p class="vv-auth-link"><a href="login.php">Return to sign in</a></p>
